<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Gallery | Asrama Putri Junjung Buyah Kukar YK</title>
    <style>
        :root { --ink: #171717; --muted: #737373; --line: #e5e5e5; --soft: #fafafa; --yellow: #ffe51f; --green: #078455; --red: #b42318; }
        * { box-sizing: border-box; } body { margin: 0; color: var(--ink); background: #fff; font-family: Inter, system-ui, sans-serif; } a { color: inherit; text-decoration: none; } button, input, select, textarea { font: inherit; }
        .topbar { height: 61px; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 0 28px; border-bottom: 1px solid var(--line); } .brand { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: 14px; white-space: nowrap; } .brand img { width: 29px; height: 29px; border-radius: 50%; object-fit: cover; } .brand strong { color: var(--ink); } .top-search { display: flex; align-items: center; gap: 10px; width: min(385px, 34vw); padding: 9px 12px; border: 1px solid var(--line); border-radius: 8px; color: #999; } .top-search input { width: 100%; border: 0; outline: 0; font-size: 13px; } .shortcut { padding: 3px 7px; border: 1px solid var(--line); border-radius: 4px; font-size: 10px; } .top-actions { display: flex; gap: 8px; } .icon-button { width: 39px; height: 39px; border: 1px solid var(--line); border-radius: 8px; color: var(--muted); background: #fff; }
        main { max-width: 1650px; margin: auto; padding: 29px 24px 60px; } h1 { margin: 0; font-size: 25px; letter-spacing: -.04em; } .intro { margin: 6px 0 24px; color: var(--muted); font-size: 14px; } .page-head { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 24px; } .head-actions { display: flex; gap: 8px; } .button { padding: 11px 15px; border: 1px solid var(--line); border-radius: 8px; color: var(--ink); background: #fff; font-size: 12px; font-weight: 800; cursor: pointer; } .button.primary { border-color: var(--ink); color: #fff; background: var(--ink); }
        .notice, .errors { margin-bottom: 18px; padding: 12px 15px; border-radius: 8px; font-size: 13px; } .notice { color: #166534; background: #ecfdf5; } .errors { color: var(--red); background: #fff1f1; } .errors ul { margin: 0; padding-left: 18px; }
        .add-panel { display: none; margin-bottom: 20px; padding: 22px; border: 1px solid var(--line); border-radius: 11px; background: var(--soft); } .add-panel.open { display: block; } .add-panel h2 { margin: 0 0 18px; font-size: 17px; } .add-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; } .field { display: grid; gap: 7px; } .field label { font-size: 11px; font-weight: 800; } .field input, .field select, .field textarea { width: 100%; padding: 10px; border: 1px solid #ddd; border-radius: 8px; outline: 0; background: #fff; font-size: 13px; } .field textarea { resize: vertical; } .field-full { grid-column: 1 / -1; } .form-actions { display: flex; justify-content: end; margin-top: 16px; }
        .panel { overflow: hidden; border: 1px solid var(--line); border-radius: 9px; } .panel-head { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 16px 20px; border-bottom: 1px solid var(--line); } .tabs { display: flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: 7px; } .tab { padding: 9px 15px; border: 0; border-radius: 5px; color: var(--muted); background: transparent; font-size: 13px; cursor: pointer; } .tab.active { color: #fff; background: var(--ink); font-weight: 800; } .search { display: flex; align-items: center; gap: 10px; width: 290px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px; color: #999; } .search input { width: 100%; border: 0; outline: 0; font-size: 13px; } .count { padding: 0 20px 15px; color: var(--muted); font-size: 12px; text-align: right; }
        .gallery { display: grid; grid-template-columns: repeat(3, 1fr); gap: 17px; padding: 0 20px 20px; background: #fcfcfc; } .media { overflow: hidden; border: 1px solid var(--line); border-radius: 12px; background: #fff; } .media img, .media video { display: block; width: 100%; height: 190px; object-fit: cover; background: #222; } .media-info { padding: 15px; } .media-info strong { display: block; margin-bottom: 6px; font-size: 14px; } .media-info small { display: block; min-height: 31px; color: var(--muted); font-size: 12px; line-height: 1.5; } .media-actions { display: flex; gap: 8px; margin-top: 14px; } .media-actions .edit, .media-actions .delete { display: inline-flex; align-items: center; justify-content: center; min-width: 78px; padding: 8px 11px; border: 1px solid; border-radius: 8px; font-size: 11px; font-weight: 800; cursor: pointer; transition: transform .2s, box-shadow .2s, background .2s; } .media-actions .edit { border-color: #eadb62; color: #675900; background: #fff8c9; } .media-actions .delete { border-color: #ffc8c8; color: var(--red); background: #fff5f5; } .media-actions button:hover { transform: translateY(-2px); box-shadow: 0 7px 15px #17171714; } .media-actions .edit:hover { background: #ffef80; } .media-actions .delete:hover { background: #ffe7e7; }
        .edit-form { display: none; gap: 9px; margin-top: 13px; } .edit-form.open { display: grid; } .edit-form input, .edit-form select, .edit-form textarea { padding: 8px; font-size: 12px; } .edit-form-actions { display: flex; gap: 7px; } .submit { padding: 9px 12px; border: 0; border-radius: 7px; color: var(--ink); background: var(--yellow); font-size: 11px; font-weight: 800; cursor: pointer; } .edit-form-actions .delete { padding: 8px 11px; border: 1px solid #ffc8c8; border-radius: 7px; color: var(--red); background: #fff5f5; font-size: 11px; cursor: pointer; } .empty { grid-column: 1 / -1; padding: 50px; color: var(--muted); text-align: center; }
        @media (max-width: 900px) { .top-search { display: none; } .page-head { align-items: flex-start; flex-direction: column; } .head-actions { width: 100%; } .head-actions .button { flex: 1; text-align: center; } .add-grid { grid-template-columns: repeat(2, 1fr); } .gallery { grid-template-columns: repeat(2, 1fr); } .panel-head { align-items: flex-start; flex-direction: column; } .search { width: 100%; } } @media (max-width: 560px) { .topbar { padding: 0 16px; } main { padding: 24px 14px 45px; } .add-grid, .gallery { grid-template-columns: 1fr; } .field-full { grid-column: auto; } .tabs { width: 100%; } .tab { flex: 1; } }
        #video-field[hidden], [data-edit-file][hidden], [data-edit-video][hidden] { display: none; }
        html[data-theme="dark"] body { color: #f4f4f4; background: #111; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .add-panel, html[data-theme="dark"] .media { background: #191919; border-color: #333; } html[data-theme="dark"] .top-search, html[data-theme="dark"] .icon-button, html[data-theme="dark"] .button, html[data-theme="dark"] .search { color: #eee; background: #191919; border-color: #444; } html[data-theme="dark"] input, html[data-theme="dark"] select, html[data-theme="dark"] textarea { color: #eee; background: #222; border-color: #444; } html[data-theme="dark"] .gallery { background: #141414; } html[data-theme="dark"] .brand strong, html[data-theme="dark"] h1, html[data-theme="dark"] h2 { color: #fff; }
        :root { --ink: #17201d; --muted: #68736f; --line: #e5e9e6; --soft: #f7f9f6; --yellow: #d8ff27; }
        body { background: radial-gradient(circle at 90% 0, #e9f7c8 0, transparent 28%), #f4f7f3; } .topbar { position: sticky; top: 0; z-index: 4; height: 68px; padding: 0 34px; background: rgba(255,255,255,.9); backdrop-filter: blur(16px); } main { max-width: 1560px; padding: 42px 34px 70px; } .panel { border-radius: 16px; box-shadow: 0 14px 40px rgba(23,32,29,.07); } .media { border-radius: 14px; } .gallery { background: #fbfcfa; }
        html[data-theme="dark"] body { color: #f3f7f4; background: #101412; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .add-panel, html[data-theme="dark"] .media { background: #1a211e; border-color: #35413b; } html[data-theme="dark"] .gallery { background: #151b18; } html[data-theme="dark"] .media-info strong, html[data-theme="dark"] h1, html[data-theme="dark"] h2, html[data-theme="dark"] .brand strong { color: #f3f7f4; } html[data-theme="dark"] .media-info small { color: #aebdb4; } html[data-theme="dark"] input, html[data-theme="dark"] select, html[data-theme="dark"] textarea, html[data-theme="dark"] .search { color: #f3f7f4; background: #202923; border-color: #4a5a50; }
    </style>
    <script>document.documentElement.dataset.theme = localStorage.getItem('admin-theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');</script>
</head>
<body>
    <header class="topbar"><a class="brand" href="{{ route('admin.dashboard') }}"><img src="{{ asset('images/logo-siap-kukar.png') }}" alt="Logo Asrama Putri Junjung Buyah Kukar YK"><span>Asrama Putri Junjung Buyah Kukar YK</span><span>›</span><strong>Kelola Gallery</strong></a><div class="top-search"><span>⌕</span><input id="global-search" placeholder="Cari judul, keterangan, media..."><span class="shortcut">Ctrl K</span></div><div class="top-actions"><button class="icon-button" type="button" aria-label="Notifikasi">♧</button><button class="icon-button" type="button" id="theme-toggle" aria-label="Ganti mode warna">☼</button></div></header>
    <main>
        <div class="page-head"><div><h1>Kelola Gallery</h1><p class="intro">Kelola foto dan video Asrama Putri Kutai Kartanegara. Gunakan judul <strong>Foto Bersama</strong> untuk menampilkan foto utama di landing page.</p></div><div class="head-actions"><a class="button" href="{{ route('admin.dashboard') }}">Dashboard</a><button class="button primary" id="add-button" type="button">＋ Tambah Media</button></div></div>
        @if (session('success')) <div class="notice">{{ session('success') }}</div> @endif @if ($errors->any()) <div class="errors"><ul>@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div> @endif
        <section class="add-panel" id="add-panel"><h2>Tambah Media</h2><form method="POST" action="{{ route('admin.gallery.store') }}" enctype="multipart/form-data">@csrf<div class="add-grid"><div class="field"><label>Judul</label><input name="judul" required></div><div class="field"><label>Tanggal</label><input type="date" name="tanggal" value="{{ now()->format('Y-m-d') }}"></div><div class="field"><label>Kategori</label><select name="kategori" required><option value="fasilitas">Fasilitas</option><option value="kamar">Kamar</option><option value="kegiatan">Kegiatan</option></select></div><div class="field"><label>Jenis Media</label><select name="jenis" id="jenis" required><option value="foto">Foto</option><option value="video">Video</option></select></div><div class="field field-full"><label>Keterangan</label><textarea name="keterangan" rows="3" maxlength="2000" placeholder="Jelaskan isi foto atau video..."></textarea></div><div class="field" id="file-field"><label>File Foto</label><input type="file" name="file[]" multiple accept=".jpg,.jpeg,.png,.webp"><small>JPG/PNG/WEBP, maksimal 50 MB.</small></div><div class="field" id="video-field" hidden><label>Link Video</label><input type="url" name="video_url" placeholder="https://contoh.com/video.mp4"><small>Link HTTPS, YouTube, Vimeo, atau Google Drive.</small></div></div><div class="form-actions"><button class="submit" type="submit">Simpan Media</button></div></form></section>
        <section class="panel"><div class="panel-head"><div class="tabs"><button class="tab active" type="button" data-filter="all">Semua Media</button><button class="tab" type="button" data-filter="foto">Foto</button><button class="tab" type="button" data-filter="video">Video</button></div><div class="search"><span>⌕</span><input id="media-search" placeholder="Cari media..."></div></div><div class="count">Menampilkan <span id="media-count">{{ $galleries->count() }}</span> media.</div><div class="gallery" id="gallery-list">@forelse ($galleries as $gallery)<article class="media" data-type="{{ $gallery->jenis }}" data-search="{{ strtolower($gallery->judul.' '.$gallery->keterangan) }}">@if ($gallery->jenis === 'foto')<img src="{{ asset('storage/'.$gallery->file_path) }}" alt="{{ $gallery->judul }}">@else<video controls src="{{ $gallery->file_path }}"></video>@endif<div class="media-info"><strong>{{ $gallery->judul }}</strong><small>{{ $gallery->keterangan ?: 'Tidak ada keterangan.' }}</small><div class="media-actions"><button class="edit" type="button" data-edit="{{ $gallery->id }}">✎ Edit</button><form method="POST" action="{{ route('admin.gallery.destroy', $gallery) }}" onsubmit="return confirm('Hapus media ini?')">@csrf @method('DELETE')<button class="delete" type="submit">⌫ Hapus</button></form></div><form class="edit-form" id="edit-{{ $gallery->id }}" method="POST" action="{{ route('admin.gallery.update', $gallery) }}" enctype="multipart/form-data">@csrf @method('PATCH')<input name="judul" value="{{ $gallery->judul }}" required><input type="date" name="tanggal" value="{{ $gallery->tanggal?->format('Y-m-d') }}"><select name="kategori"><option value="fasilitas" @selected($gallery->kategori === 'fasilitas')>Fasilitas</option><option value="kamar" @selected($gallery->kategori === 'kamar')>Kamar</option><option value="kegiatan" @selected($gallery->kategori === 'kegiatan')>Kegiatan</option></select><label><input type="checkbox" name="terlihat" value="1" @checked($gallery->terlihat)> Tampil publik</label><label><input type="checkbox" name="unggulan" value="1" @checked($gallery->unggulan)> Foto unggulan</label><textarea name="keterangan" rows="3" maxlength="2000" placeholder="Keterangan">{{ $gallery->keterangan }}</textarea><select name="jenis" data-edit-type="{{ $gallery->id }}"><option value="foto" @selected($gallery->jenis === 'foto')>Foto</option><option value="video" @selected($gallery->jenis === 'video')>Video</option></select><div data-edit-file="{{ $gallery->id }}" @if ($gallery->jenis !== 'foto') hidden @endif><input type="file" name="file" accept=".jpg,.jpeg,.png,.webp"></div><div data-edit-video="{{ $gallery->id }}" @if ($gallery->jenis !== 'video') hidden @endif><input type="url" name="video_url" placeholder="Link video baru"></div><div class="edit-form-actions"><button class="submit" type="submit">Simpan</button><button class="delete" type="button" data-cancel="{{ $gallery->id }}">Batal</button></div></form></div></article>@empty<div class="empty">Belum ada foto atau video.</div>@endforelse</div></section>
    </main>
    <script>
        const jenis = document.querySelector('#jenis'); const fileField = document.querySelector('#file-field'); const videoField = document.querySelector('#video-field'); const fileInput = document.querySelector('input[name="file[]"]'); const videoInput = document.querySelector('input[name="video_url"]');
        jenis.addEventListener('change', () => { const isVideo = jenis.value === 'video'; fileField.hidden = isVideo; videoField.hidden = !isVideo; fileInput.required = !isVideo; fileInput.disabled = isVideo; videoInput.required = isVideo; videoInput.disabled = !isVideo; });
        document.querySelectorAll('[data-edit]').forEach((button) => button.addEventListener('click', () => document.querySelector(`#edit-${button.dataset.edit}`).classList.add('open')));
        document.querySelectorAll('[data-cancel]').forEach((button) => button.addEventListener('click', () => document.querySelector(`#edit-${button.dataset.cancel}`).classList.remove('open')));
        document.querySelectorAll('[data-edit-type]').forEach((select) => select.addEventListener('change', () => { const id = select.dataset.editType; document.querySelector(`[data-edit-file="${id}"]`).hidden = select.value !== 'foto'; document.querySelector(`[data-edit-video="${id}"]`).hidden = select.value !== 'video'; }));
        const search = document.querySelector('#media-search'); const globalSearch = document.querySelector('#global-search'); const cards = [...document.querySelectorAll('.media[data-search]')]; const tabs = [...document.querySelectorAll('[data-filter]')]; let filter = 'all';
        const applyFilter = () => { const query = search.value.toLowerCase().trim(); let visible = 0; cards.forEach((card) => { const show = (filter === 'all' || card.dataset.type === filter) && card.dataset.search.includes(query); card.hidden = !show; if (show) visible += 1; }); document.querySelector('#media-count').textContent = visible; };
        search.addEventListener('input', applyFilter); globalSearch.addEventListener('input', () => { search.value = globalSearch.value; applyFilter(); }); tabs.forEach((tab) => tab.addEventListener('click', () => { tabs.forEach((item) => item.classList.remove('active')); tab.classList.add('active'); filter = tab.dataset.filter; applyFilter(); })); document.querySelector('#add-button').addEventListener('click', () => document.querySelector('#add-panel').classList.toggle('open')); document.addEventListener('keydown', (event) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); globalSearch.focus(); } });
    </script>
<script>const themeToggle=document.querySelector('#theme-toggle');const setTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';themeToggle.textContent=dark?'☀':'☾';themeToggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('admin-theme',next);themeToggle.textContent=next==='dark'?'☀':'☾';};};setTheme();</script></body>
</html>
